(*
【需求原文】
An automated production line consists of 5 workstations: material loading
station, cleaning station, weighing station, firing station, and finished
product station. The production line has a motor responsible for moving
products from one workstation to the next, the sequence of the line is
from the material loading station, cleaning station, weighing station,
firing station, to the finished product station. Each workstation has a
sensor (used to detect if the product has arrived).
Control requirements:
1. Mode Switching: The mode switch (Mode) is used to switch between manual
and automatic modes of the production line. 0 = manual mode, 1 = automatic mode.
2. Manual Mode: In manual mode, the forward rotation button (ForwardButton)
controls the forward rotation of the motor, and the reverse rotation button
(ReverseButton) controls the reverse rotation of the motor. Forward and
reverse rotation operations need to be interlocked and cannot be performed
simultaneously.
3. Automatic Mode:
   - When the material arrives at the material loading station, the SensorFeed
detects the material, the motor starts forward rotation, and moves the material
to the cleaning station.
   - When the material arrives at the cleaning station, the SensorWash detects
the material, the motor stops, and upon receiving the signal washComplete after
cleaning is finished, the motor starts forward rotation, moving the material
to the weighing station.
   - When the material arrives at the weighing station, the SensorWeight detects
the material, the motor stops, and upon receiving weightComplete after weighing
is complete, the material is judged to be qualified based on the weight value.
If the weight value is greater than or equal to 100 and less than or equal to
200, it is qualified, otherwise not.
     If the material is unqualified, the rejection command kick is initiated.
     If the material is qualified, the firing temperature is calculated based
on the weight value. The calculation rule is that the weight value from 100
to 200 linearly corresponds to the temperature value from 500 to 550.
The firing temperature firingTemp is output. At the same time, the motor
starts forward rotation, moving the material to the firing station.
   - When the product arrives at the firing station, the SensorFiring detects
the material, the motor stops, and upon receiving the signal firingComplete
after firing is finished, the motor starts forward rotation, moving the product
to the finished product station.
   - When the product arrives at the finished product station, the SensorOutput
detects the product, the motor stops, and the completion light (CompletionLight)
turns on, indicating that the product processing is complete. When the product
is taken away, i.e., the SensorOutput does not detect the product, the completion
light (CompletionLight) turns off.

中文摘要：五工位生产线：手动正反转互斥，自动按上料→清洗→称重→烧成→成品
顺序推进，各工位完成信号触发推进，成品站执行 kick 动作。

扫描周期：20 ms。
初态：MotorForward=FALSE，MotorReverse=FALSE，kick=FALSE，
CompletionLight=FALSE，工位状态=IDLE。

K1 手动模式下 MotorForward 与 MotorReverse 互斥。
K2 自动模式下产品依次经过五个工位，不得跳站。
K3 完成信号是推进的必要条件，且必须与对应到位传感器一致。
K4 成品站完成出料动作 kick 后点亮 CompletionLight。

C4: G(!(MotorForward && MotorReverse))
C2: G(kick -> SensorOutput)
C1: G(CompletionLight -> X(!kick))
C6: G(CompletionLight -> (CompletionLight W !SensorOutput))
C10: G[0,1](!MotorForward && !MotorReverse && !kick && !CompletionLight)

【数据冲突报告：待审】
输入 semantic_warnings 和 warnings 虽为空，但英文原文要求称重不合格时
发出 kick；K4、中文摘要及 C2 将 kick 约束为成品站到位时的出料动作。
SensorWeight 与 SensorOutput 没有必然同时为真的条件，因此这两类要求
不能在所有输入轨迹上同时满足。以下逻辑保留该冲突：不合格进入内部
待审保持状态，停止自动输送，不擅自增加不合格品输送或出料流程。
该分支不宣称已实现英文原文的立即剔除要求。

英文原文要求成品到位点灯，K4 要求出料后点灯。本实现采用两个扫描阶段：
成品到位时停止并输出一周期 kick，下一扫描仍到位才点灯。
此时序差异仍须需求审定。

C10 的 [0,1] 按前两个调用均禁止布尔输出解释。
完成信号按电平确认；只在对应等待状态且对应传感器为 TRUE 时接受。
模式切换清除自动工序状态，但已点亮的完成灯保持至 SensorOutput 为 FALSE。
无独立复位输入；待审状态通过进入手动模式退出，重新进入自动模式从 IDLE 开始。
未经过真实编译器或逐周期测试验证。
*)

FUNCTION_BLOCK FB_P20
VAR_INPUT
    Mode : BOOL;
    ForwardButton : BOOL;
    ReverseButton : BOOL;
    SensorFeed : BOOL;
    SensorWash : BOOL;
    SensorWeight : BOOL;
    SensorFiring : BOOL;
    SensorOutput : BOOL;
    washComplete : BOOL;
    weightComplete : BOOL;
    weight : REAL;
    firingComplete : BOOL;
END_VAR

VAR_OUTPUT
    MotorForward : BOOL := FALSE;
    MotorReverse : BOOL := FALSE;
    kick : BOOL := FALSE;
    CompletionLight : BOOL := FALSE;
    firingTemp : REAL := 0.0;
END_VAR

VAR
    (* 0=IDLE, 10=向清洗输送, 20=等待清洗完成,
       30=向称重输送, 40=等待称重完成,
       50=向烧成输送, 60=等待烧成完成,
       70=向成品输送, 80=出料后的点灯阶段,
       90=等待成品移走, 100=不合格需求冲突待审。 *)
    stationState : INT := 0;
    startupScans : USINT := 0;
    previousMode : BOOL := FALSE;
    previousLight : BOOL := FALSE;
    modeChanged : BOOL := FALSE;
END_VAR

(* 每次扫描重新计算瞬时命令；温度与完成灯另行保持。 *)
MotorForward := FALSE;
MotorReverse := FALSE;
kick := FALSE;

IF startupScans < 2 THEN
    startupScans := startupScans + 1;
    stationState := 0;
    CompletionLight := FALSE;
    firingTemp := 0.0;
    previousMode := Mode;
    previousLight := FALSE;
ELSE
    modeChanged := Mode <> previousMode;

    (* C6：模式切换不清除仍然到位的完成灯。 *)
    IF NOT SensorOutput THEN
        CompletionLight := FALSE;
    END_IF;

    IF modeChanged THEN
        stationState := 0;
    END_IF;

    IF NOT Mode THEN
        stationState := 0;

        (* 两按钮同时按下时两方向均不输出。 *)
        MotorForward := ForwardButton AND NOT ReverseButton;
        MotorReverse := ReverseButton AND NOT ForwardButton;

    ELSIF NOT modeChanged THEN
        CASE stationState OF
            0:
                (* 已完成的产品未移走时不开始下一自动周期。 *)
                IF NOT CompletionLight AND NOT previousLight THEN
                    IF SensorFeed THEN
                        firingTemp := 0.0;
                        stationState := 10;

                        IF SensorWash THEN
                            stationState := 20;
                        ELSE
                            MotorForward := TRUE;
                        END_IF;
                    END_IF;
                END_IF;

            10:
                IF SensorWash THEN
                    stationState := 20;
                ELSE
                    MotorForward := TRUE;
                END_IF;

            20:
                IF SensorWash AND washComplete THEN
                    stationState := 30;

                    IF SensorWeight THEN
                        stationState := 40;
                    ELSE
                        MotorForward := TRUE;
                    END_IF;
                END_IF;

            30:
                IF SensorWeight THEN
                    stationState := 40;
                ELSE
                    MotorForward := TRUE;
                END_IF;

            40:
                IF SensorWeight AND weightComplete THEN
                    (* 闭区间判断；只有合格值参与温度计算。 *)
                    IF (weight >= 100.0) AND (weight <= 200.0) THEN
                        firingTemp := 500.0 + (weight - 100.0) * 0.5;

                        IF firingTemp < 500.0 THEN
                            firingTemp := 500.0;
                        ELSIF firingTemp > 550.0 THEN
                            firingTemp := 550.0;
                        END_IF;

                        stationState := 50;
                        IF SensorFiring THEN
                            stationState := 60;
                        ELSE
                            MotorForward := TRUE;
                        END_IF;
                    ELSE
                        (* 原文剔除与 C2 冲突：保持待审，不发 kick。 *)
                        stationState := 100;
                    END_IF;
                END_IF;

            50:
                IF SensorFiring THEN
                    stationState := 60;
                ELSE
                    MotorForward := TRUE;
                END_IF;

            60:
                IF SensorFiring AND firingComplete THEN
                    stationState := 70;

                    IF SensorOutput THEN
                        IF NOT CompletionLight AND NOT previousLight THEN
                            kick := TRUE;
                            stationState := 80;
                        END_IF;
                    ELSE
                        MotorForward := TRUE;
                    END_IF;
                END_IF;

            70:
                IF SensorOutput THEN
                    IF NOT CompletionLight AND NOT previousLight THEN
                        kick := TRUE;
                        stationState := 80;
                    END_IF;
                ELSE
                    MotorForward := TRUE;
                END_IF;

            80:
                (* 前一扫描已执行 kick；本扫描 kick 默认为 FALSE。 *)
                IF SensorOutput THEN
                    CompletionLight := TRUE;
                    stationState := 90;
                ELSE
                    stationState := 0;
                END_IF;

            90:
                IF NOT SensorOutput THEN
                    stationState := 0;
                END_IF;

            100:
                (* 待审保持：不自动推进，也不将剔除偷换为成品出料。 *)
                MotorForward := FALSE;
                MotorReverse := FALSE;
                kick := FALSE;

        ELSE
            (* 内部非法状态回到安全停止的 IDLE。 *)
            stationState := 0;
        END_CASE;
    END_IF;

    (* 输出端保护：C2 与 C1；完成灯亮时也禁止重复出料。 *)
    IF NOT SensorOutput OR previousLight OR CompletionLight THEN
        kick := FALSE;
    END_IF;

    (* 双方向命令冲突时安全停机。 *)
    IF MotorForward AND MotorReverse THEN
        MotorForward := FALSE;
        MotorReverse := FALSE;
    END_IF;

    previousMode := Mode;
    previousLight := CompletionLight;
END_IF;

END_FUNCTION_BLOCK
